mapper.select:
SELECT

FROM pur_yt_purchase_item
WHERE is_deleted = 0

    AND purchase_id = #{purchaseId}


    AND product_id = #{productId}


    AND specification_id = #{specificationId}


    AND status = #{status}


    AND customer_id = #{customerId}


    AND customer_name LIKE CONCAT('%', #{customerName}, '%')

ORDER BY create_time DESC

SELECT pypi.*,pyp.code as productCode, (select code from sal_yt_order where id in (select order_id from sal_yt_order_sub where id = pypi.order_sub_id)) as orderCode, (select nick_name from sys_user where user_id = pypi.sales_employee_id) as salesEmployeeName, (select delivery_number from sal_yt_order_sub_item where id =pypi.order_sub_item_id) as deliveryNumber FROM pur_yt_purchase_item AS pypi LEFT JOIN pro_yt_product_specification AS pyps ON pypi.specification_id = pyps.id AND pyps.is_deleted = 0 LEFT JOIN pro_yt_product AS pyp ON pypi.product_id = pyp.id AND pyp.is_deleted = 0 WHERE pypi.is_deleted = 0 and pypi.specification_id is not null
AND pypi.purchase_id = #{purchaseId}
AND pypi.order_sub_id = #{orderSubId}
AND (select order_id from sal_yt_order_sub where id = pypi.order_sub_id) in (select id from sal_yt_order where code like concat('%',#{orderCode},'%'))
AND pyps.id in (select product_specification_id from pro_yt_product_specification_item where category_specification_item_id in (select id from pro_yt_category_specification_item where value LIKE CONCAT('%', #{specificationName}, '%')))
AND pyp.code LIKE CONCAT('%', #{productCode}, '%')
AND pypi.status = #{status}
ORDER BY pypi.create_time DESC

SELECT pypi.*, CASE WHEN ( SELECT COALESCE(SUM(number), 0) FROM pur_yt_purchase_item WHERE confirm_item_id = pypi.id AND is_deleted = 0 ) < pypi.number THEN 0 ELSE 1 END AS confirmStatus, pyp.code as productCode, (select code from sal_yt_order where id in (select order_id from sal_yt_order_sub where id = pypi.order_sub_id)) as orderCode, (select nick_name from sys_user where user_id = pypi.sales_employee_id) as salesEmployeeName FROM pur_yt_purchase_item AS pypi LEFT JOIN pro_yt_product AS pyp ON pypi.product_id = pyp.id AND pyp.is_deleted = 0 WHERE pypi.is_deleted = 0 and pypi.specification_id is null
AND pypi.purchase_id = #{purchaseId}
AND pypi.order_sub_id = #{orderSubId}
AND (select order_id from sal_yt_order_sub where id = pypi.order_sub_id) in (select id from sal_yt_order where code like concat('%',#{orderCode},'%'))
AND pyp.code LIKE CONCAT('%', #{productCode}, '%')
AND CASE WHEN ( SELECT COALESCE(SUM(number), 0) FROM pur_yt_purchase_item WHERE confirm_item_id = pypi.id AND is_deleted = 0 ) < pypi.number THEN 0 ELSE 1 END = #{status}
ORDER BY pypi.create_time DESC

SELECT pypi.order_sub_item_id AS orderSubItemId, COALESCE(SUM(pypi.number), 0) AS totalNumber FROM pur_yt_purchase_item pypi INNER JOIN pur_yt_purchase pyp ON pyp.id = pypi.purchase_id WHERE pypi.is_deleted = 0 AND pyp.is_deleted = 0 AND pyp.status = '0' AND pypi.order_sub_item_id IN
#{orderSubItemId}
GROUP BY pypi.order_sub_item_id

SELECT pypi.*,pyp.code as productCode, (select sub_code from sal_yt_order_sub where id = pypi.order_sub_id) as orderSubCode, (select nick_name from sys_user where user_id = pypi.sales_employee_id) as salesEmployeeName, (select delivery_number from sal_yt_order_sub_item where id =pypi.order_sub_item_id) as deliveryNumber FROM pur_yt_purchase_item AS pypi LEFT JOIN pro_yt_product_specification AS pyps ON pypi.specification_id = pyps.id AND pyps.is_deleted = 0 LEFT JOIN pro_yt_product AS pyp ON pypi.product_id = pyp.id AND pyp.is_deleted = 0 WHERE pypi.is_deleted = 0
AND pypi.purchase_id = #{purchaseId}
AND pypi.order_sub_id = #{orderSubId}
AND pypi.order_sub_id in (select id from sal_yt_order_sub where sub_code like concat('%',#{orderSubCode},'%'))
AND pyps.id in (select product_specification_id from pro_yt_product_specification_item where category_specification_item_id in (select id from pro_yt_category_specification_item where value LIKE CONCAT('%', #{specificationName}, '%')))
AND pyp.code LIKE CONCAT('%', #{productCode}, '%')
AND pypi.status = #{status}
ORDER BY pypi.create_time DESC
